/**
 * 族索引页共用组件（/industries/、/features/、/use-cases/、/compare/ 四个索引页）
 *
 * 🔴 **为什么是一个组件而不是四份页面**：四个索引页的 JSX 逐字相同，唯一差异是
 *    「标题/简介/取哪个数组」——那就是典型的「同一规范值两处实现」，必然漂移。
 *    四个 `src/pages/<family>/index.js` 只做一件事：把 familyKey 传进来。
 *
 * 🔴 索引页的两个职责（别加第三个）：① 让爬虫一站找齐这一族的全部内链；
 *    ② 让人按自己的情况自选入口。塞营销话术会同时削弱这两件事。
 *
 * @author 恒哥
 * @since 2026-10-13
 */
import React from 'react';
import { Link } from 'gatsby';
import Layout from './Layout';
import SEO from './SEO';
import { FAMILIES } from '../data/families';
import { INDUSTRIES } from '../data/industries';
import { FEATURES } from '../data/features';
import { USE_CASES } from '../data/useCases';
import { COMPARISONS } from '../data/compare';
import { MESSAGING_CONSOLE_URL } from '../constants/brand';
import '../styles/marketing.css';

const FAMILY_DATA = {
  industries: INDUSTRIES,
  features: FEATURES,
  'use-cases': USE_CASES,
  compare: COMPARISONS,
};

export default function FamilyIndexPage({ familyKey }) {
  const family = FAMILIES[familyKey];
  const pages = FAMILY_DATA[familyKey] || [];
  const others = Object.keys(FAMILIES).filter((k) => k !== familyKey);

  return (
    <Layout>
      <SEO
        // SEO 专用的 metaTitle/metaDescription（families.js），与可见的 h1/lede 分开 ——
        // 标题要收进 SERP ~60 字符显示上限，不能为这个目的去改页面正文。
        title={family.metaTitle || `${family.label} — ${family.h1}`}
        description={family.metaDescription || family.lede}
        pathname={family.indexPath}
        softwareApp={false}
      />
      <div className="mk">
        <header className="mk-hero">
          <span className="mk-eyebrow">{family.eyebrow}</span>
          <h1>{family.h1}</h1>
          <p className="mk-lead">{family.lede}</p>
          <div className="mk-actions">
            <a className="mk-btn mk-btn-primary" href={MESSAGING_CONSOLE_URL}>
              Open the console
            </a>
            <Link className="mk-btn mk-btn-secondary" to="/messaging/">
              How the platform works
            </Link>
          </div>
        </header>

        <section className="mk-section">
          <div className="mk-grid">
            {pages.map((p) => (
              <article className="mk-card" key={p.slug}>
                <span className="mk-card-tag">{p.eyebrow || family.eyebrow}</span>
                <h3>{p.name}</h3>
                <p>{p.lede}</p>
                <Link className="mk-card-link" to={`${family.indexPath}${p.slug}/`}>
                  Read more &rarr;
                </Link>
              </article>
            ))}
          </div>
        </section>

        <section className="mk-section">
          <h2>Other sections</h2>
          <div className="mk-grid">
            {others.map((k) => (
              <article className="mk-card" key={k}>
                <span className="mk-card-tag">{FAMILIES[k].eyebrow}</span>
                <h3>{FAMILIES[k].label}</h3>
                <p>{FAMILIES[k].lede}</p>
                <Link className="mk-card-link" to={FAMILIES[k].indexPath}>
                  Open &rarr;
                </Link>
              </article>
            ))}
          </div>
        </section>

        <div className="mk-scope">
          <strong>Scope.</strong> {family.scope}
        </div>
      </div>
    </Layout>
  );
}
